	/**
	 * Default Constructor
	 */
    public ConsentService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ConsentEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ConsentRepository.class) );
		this.validator		= applicationContext.getBean(ConsentValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Consent
	 */
		public Consent createConsent( CreateConsentCommand command ) {

		Consent entity = new Consent();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setConsentId( command.getConsentId() );
            entity.setGrantedOn( command.getGrantedOn() );
            entity.setExpiresOn( command.getExpiresOn() );
            entity.setConsentType( command.getConsentType() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Consent {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateConsentCommand
	 * @return		Consent
	 */
	public Consent updateConsent( UpdateConsentCommand command ) {

		Consent entity = new Consent();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setConsentId( command.getConsentId() );
            entity.setGrantedOn( command.getGrantedOn() );
            entity.setExpiresOn( command.getExpiresOn() );
            entity.setCustomer( command.getCustomer() );
            entity.setBank( command.getBank() );
            entity.setAuthorizedAccounts( command.getAuthorizedAccounts() );
            entity.setThirdPartyProvider( command.getThirdPartyProvider() );
            entity.setConsentType( command.getConsentType() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Consent {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteConsentCommand
	 */
	public void delete( DeleteConsentCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getConsentId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Consent {0} ", id );

	}

	/**
	 * Method to retrieve the Consent via ConsentFetchOneSummary
	 * @param 	summary ConsentFetchOneSummary
	 * @return 	ConsentFetchOneResponse
	 */
	public Consent getConsent( ConsentFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ConsentFetchOneSummary arg cannot be null" );

		Consent entity = null;
		UUID id = summary.getConsentId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Consent using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Consents
	 *
	 * @return 	List<Consent>
	 */
    public List<Consent> getAllConsent() {
		List<Consent> list = projector.findAll( new FindAllConsentQuery() );
		return list;
	}

	/**
	 * assign Customer on Consent
	 * @param		command AssignCustomerToConsentCommand
	 */
	public void assignCustomer( AssignCustomerToConsentCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignCustomer(command.getConsentId(), command.getAssignment());

	}

